import heapq

def max_profit(n, costs, races):
    # Min-heap to store costs sorted by distance
    costs.sort()

    # Map of race to its cost
    race_to_cost = {}

    for race, (_, roads, cost) in enumerate(races):
        for road in range(roads - 1, roads + 1):
            if road < 1 or road > n:
                continue
            if road in race_to_cost:
                race_to_cost[road].append(cost)
            else:
                race_to_cost[road] = [cost]

    # Handle races that rely on roads not in the cost map
    for road in range(1, n + 1):
        if road not in race_to_cost:
            all_lbs = set(race_to_cost.keys())
            race_to_cost[road] = sorted(all_lbs)

    profit = 0
    for race in range(1, len(races) + 1):
        if len(race_to_cost[race]) > 1:
            lb, ub, c = races[race - 1]
            nearest = [heapq.heappop(costs) for _ in range(ub - lb)]
            max_cost = max(nearest) + c
            profit += max(0, max_cost)
            costs = [x - max_cost if x > max_cost else x for x in costs]

    return profit
