from collections import defaultdict, deque
from typing import List

def get_edges(query: List[int]) -> List[List[int]]:
    edges = [[] for _ in range(len(query) + 2)]
    parent = [-1] * (len(query) + 2)
    parent_list = [-1] * (len(query) + 2)
    for u, v in query:
        u += 1
        v += 1
        edges[u].append(v)
        edges[v].append(u)
        parent[u] = u
        parent[v] = v
    return edges, parent, parent_list

def find_ancestor(x: int, w: int, parent: List[int]) -> int:
    if parent[x] == x:
        return x
    return find_ancestor(parent[x], w, parent)

def is_choice_possible(c: List[List[int]], u: int, v: int, l: int, r: int) -> bool:
    odd_count = 0
    for x, y in c:
        a = find_ancestor(x, u, parent)
        b = find_ancestor(v, u, parent)
        if a == x and b == y or x == a and y == b:
            odd_count += 1
        elif a == y and b == x or x == b and y == a:
            odd_count -= 1
    return odd_count == 0 or (odd_count == 1 and (u in (a, b) or (a, b) == (x, y) or (x, y) == (a, b)))

def get_choices(query: List[int], parent: List[int]) -> List[int]:
    c = [[] for _ in range(len(query) + 2)]
    for i in range(len(query)):
        for j in range(len(query)):
            if i == j:
                continue
            a, b = query[i], query[j]
            if parent[a] == b and parent[b] == a:
                c[i].append((a, b))
                c[i].append((a+1, b+1))
    for i in range(len(query)):
        c[i] = sorted(c[i])
    return [[x[1], x[0]] if is_choice_possible(c, x[0], x[1], l, r) else [-1] for x in c]

