def find_min_inv(n, fact, inv_fact, max_n):
    result = [0] * n
    auxiliary = deque([0])
    current = max_n
    inv_max_n = inv_fact[1 - (max_n - 1)]  # Inverse of max n
    i = 0

    while i < n:
        while not auxiliary or auxiliary[-1] < current:
            aux_max_n = max(n - i, i)  # Remaining of the perm
            max_inv_n = inv_max_n
            min_inv_n = inv_fact[aux_max_n]
            if max_inv_n + min_inv_n > n - i:  # Not enough inversions to rotate all in aux
                current = inv_fact[aux]  # N imprecise here
                break
            for idx in range(aux_max_n, 0, -1):
                if max_inv_n + min_inv_n < fact[idx]:
                    max_inv_n += 1
            if i < aux_max_n:
                current = inv_fact[n - i]  # N here is imprecise
            else:
                current = max_inv_n  # N ie is the full one
            yield current
            for j in range(aux_max_n, -1, -1):
                current -= fact[j] + inv_fact[j]
            aux = auxiliary.pop()
            auxiliary.appendleft(aux + current)
        i += 1

    # Copy terminal results
    m = max(auxiliary)
    for idx in range(n-1, -1, -1):
        result[idx] = m


