def main():
    n = int(input())
    meteors = []
    for _ in range(n):
        t1, x1, y1, t2, x2, y2 = map(int, input().split())
        dx = x2 - x1
        dy = y2 - y1
        vel = (dx, dy)
        t0 = t1 + 2 ** (n - 1)
        duration = t2 - t1
        dx0, dy0 = map(t0, (x1, y1))
        dx1, dy1 = map(t2, vel)
        fx = lambda t0: dx * (t0 - t1) + dx0
        fy = lambda t0: dy * (t0 - t1) + dy0
        interact_points = [
            (t0 + pom, fx(pom) + pom * fy(pom))
            for pom in range(t0, t2, -duration)
        ]
        meteors.append((vel, (dx, dy), interact_points))

    meteor_ids = list(range(n))
    for i, (vel, pos, interact_points) in enumerate(meteors):
        first_state = pos[0]
        last_state = pos[0] + vel[0]
        all_interact_points = set([p for x, y in interact_points if first_state + evans_helper(x, 0) - first_state in [p for x, y in interact_points]])
        if first_state + vel[0] < last_state:
            all_interact_points.update([p for x, y in interact_points if last_state + evans_helper(x, 0) < last_state + evans_helper(x - 1, 0)])
        evolved_interact_points = set()
        for dx, dy in evolve_all(all_interact_points):
            if dx in meteor_ids:
                evolved_interact_points.add(dy)
        meteor_ids = list(meteor_ids)
        meteor_ids.sort(key=lambda x: -len(evolved_interact_points[x]))
        meteor_ids = meteor_ids[:len(evolved_interact_points)]
    print(len(meteor_ids))

def evans_helper(x, y):
    return x + gcd(_gcd_helper(x, y) * y, _gcd_helper(y, x))

def _gcd_helper(x, y):
    return x % y or _gcd_helper(y, x % y)

def evolve_all(interact_points):
    for i in range(len(interact_points) - 1):
        x1, y1 = interact_points[i]
        x2, y2 = interact_points[i + 1]
        if abs(y1 - y2) > abs(x1 - x2):
            if (y1 - y2) % 2 == 0:
                yield (x1, y1), (x2, y2 + (x2 - x1) // abs(y1 - y2))
            else:
                yield (x1, y1), (x2, y2 - (x2 - x1) // abs(y1 - y2))
        else:
            if (x1 - x2) % 2 == 0:
                yield (x1, y1 + (y1 - y2) // abs(x1 - x2)), (x2, y2)
            else:
                yield (x1, y1 - (y1 - y2) // abs(x1 - x2))
    yield interact_points[-1]

if __name__ == '__main__':
