def count_primes(n):
    primes = [True] * (n + 1)
    p = 2
    while (p * p <= n):
        if (primes[p] == True):
            for i in range(p * p, n + 1, p):
                primes[i] = False
        p += 1
    prime_factors = []
    for p in range(2, n + 1):
        if primes[p]:
            prime_factors.append(p)
    return prime_factors


def sum_operations(prime_factors_list):
    n = len(prime_factors_list)
    dp = [i for i in range(n + 1)]
    for prime in prime_factors_list:
        for i in range(prime, n + 1):
            dp[i] += dp[i - prime]
            dp[i] %= 1000000007
    return sum(dp[:n + 1]) % 1000000007


