import math

def build_museum(m, perishabilities):
    n = len(perishabilities)
    limit = 1 << (n - 1)
    parts = [0] * limit

    def generate_partitions(n, i, j, current):
        for k in range(j, n + 1):
            if j != 0:
                parts[j] += current
            if k - i + 1 > 0:
                generate_partitions(n - 1, i + 1, k + 1, current + 1)

    generate_partitions(n, 0, limit, 0)
    total = 0
    H = [0] * (n - 1)
    for i in range(n):
        total += 1
        k = i + math.inf // (limit << (n - i - 1))
        while k < limit:
            cur = parts[k]
            q = (total * k) // n
            while math.inf - q * (limit * (limit + 1) // 2) < k:
                k = k + (limit << (n - i - 1))
            if cur > H[0]:
                H[0] = cur
            H[i + 1] += H[i]
    return sum(min(1000000000, e) for e in H)


def optimize_museum_buildings(n, perishabilities):
