import math
from itertools import permutations

def is_good(perm):
    decomposition = []
    p = [i for i in range(1, len(perm)+1)]
    while any(p):
        leftmost = min(i for i, x in enumerate(p) if x == p[i-1] and x != x%len(p))
        reachable = [i for i, x in enumerate(p) if not p[i] and (leftmost == p[i] or x in p)]
        if not reachable:
            return False
        if max(reachable) != reachable[0]:
            temp_reachable = list(reversed(reachable))
            temp_reachable[-1] = temp_reachable[temp_reachable.index(max(p))] if len(temp_reachable) else 0
            for i, x in enumerate(temp_reachable):
                p[i], p[x] = x, i
            p = [p[abs(max(p))] for p in p]
        else:
            temp_reachable = [p[0]]
            for i, x in enumerate(reachable):
                temp_reachable.append(p[x])
            for i, x in enumerate(temp_reachable):
                p[i], p[x] = x, i
            p.extend(x+abs(x) for x in reachable)
        p = p[:abs(max(p))]
        decomposition.append(reachable)
    return True

def next_good(n, k):
    for i, perm in enumerate(permutations(range(1, n+1))):
        if is_good(perm):
            if len(permutations(perm)) >= k:
                return ''.join(str(x) for x in perm)
            k -= len(permutations(perm))
    return -1

