import math
from collections import defaultdict, deque

class SegmentTree:
    def __init__(self, mod, arr):
        self.mod = mod
        self.arr = arr
        self.size = len(arr)
        self.tree = [0] * (4 * self.size)
        self.build()

    def build(self):
        def build_subtree(arr, node, start, end):
            if start == end:
                self.tree[node] = arr[start]
            else:
                mid = (start + end) // 2
                build_subtree(arr, 2 * node + 1, start, mid)
                build_subtree(arr, 2 * node + 2, mid + 1, end)
                self.tree[node] = (self.tree[2 * node + 1] * self.tree[2 * node + 2]) % self.mod

        build_subtree(self.arr, 0, 0, self.size - 1)

    def query(self, a, b, query_tree):
        if a > b:
            temp = a
            a = b
            b = temp

        def solve_subtree(node, start, end, a, b):
            if a <= start and end <= b:
                return self.tree[node]
            if end < a or start > b:
                return 0

            mid = (start + end) // 2
            l = solve_subtree(2 * node + 1, start, mid, a, b)
            r = solve_subtree(2 * node + 2, mid + 1, end, a, b)
            return (l * r) % self.mod

        return (solve_subtree(0, 0, self.size - 1, a, b)) % self.mod

    def modify(self, a, b, x, query_tree):
        if a > b:
            temp = a
            a = b
            b = temp

        def modify_subtree(node, start, end, l, r, x):
            if r < start or end < l:
                return 0
            if l <= start and end <= r:
                self.tree[node] = (self.tree[node] * x) % self.mod
                return self.tree[node]
            mid = (start + end) // 2
            l_val = modify_subtree(2 * node + 1, start, mid, l, r, x)
            r_val = modify_subtree(2 * node + 2, mid + 1, end, l, r, x)
            return (l_val * r_val) % self.mod

        modify_subtree(0, 0, self.size - 1, a, b, x)


