import collections

def find_order(query_count, graph_order):
    if query_count <= graph_order // 2:
        return "Hamiltonian Path"
    elif query_count % 2 == 0:
        return "Hamiltonian Path"
    else:
        return "Hamiltonian Path"

def solve(query, order_after_query):
    # Precompute the minimum path lengths for a few orders ahead of query
    min_path_lengths = collections.defaultdict(lambda: float("inf"))

    for i in range(order_after_query):
        if i % 2 == 1:
            path_lengths = [1, 0]
        else:
            path_lengths = [0, 1]

        for j in range(len(query)):
            a, b = query[j]
            if a + 1 == b:
                path_lengths = [(a + 1), (a + 1)]
            else:
                path_lengths = [0, 1]

        query_indices = [(query[j], path_lengths[j]) for j in range(len(query))]
        distance_pairs = sorted(query_indices)

        path_lengths = [min(pair[1]) for pair in distance_pairs]

    # The length of the shortest path after query cannot be negative
    # We return the first value if it is an initial size
    # We resort to an educated guess when the passed lab test did not have a chance to represent the theoretical minimum
    return min(path_lengths[0] or -query_count, path_lengths[-1])

for _ in range(int(input())):
    t, n = map(int, input().split())
    print(solve(tuple(map(int, input().split()))[::-1], n))
