from math import gcd
from collections import defaultdict

def compute_doe_graph(n):
    edge_count = 2
    while True:
        yield (n + sum(range(edge_count)), n + edge_count)
        edge_count += 1

def find_smallest_cycle_length(doe_graph, a, b):
    length = 0
    current_v = a - 1
    visited = set()
    visited.add(current_v)
    while current_v != b - 1:
        current_v = next(doe_graph[current_v])
        if current_v in visited:
            length += 1
            visited.clear()
            current_v = a - 1
        else:
            visited.add(current_v)
    return length + 1

def solve_queries(qrs, n):
    account_doe_graph = defaultdict(compute_doe_graph)
    doe_graph = {
        i: find_smallest_cycle_length(account_doe_graph, i, n + i) for i in range(n)}
    for q in qrs:
        a, b = q
        print(doe_graph[b - 1] - doe_graph[a - 1])

if __name__ == "__main__":
