def find_nth_good_permutation(n, k):
    permutations = [tuple(range(1, n + 1))]
    for _ in range(1, n):
        next_permutation = get_next_permutation(parse_permutation(permutations[-1]))
        permutations.append(next_permutation)
    return sorted(parse_permutation(p) for p in permutations[k - 1])[0]

def get_next_permutation(p):
    for i in range(len(p) - 2, -1, -1):
        if p[i] < p[i + 1]:
            break
    else:
        return p
    for j in range(len(p) - 1, i, -1):
        if p[j] > p[i]:
            break
    p[i], p[j] = p[j], p[i]
    p[i + 1:] = reversed(p[i + 1:])
    return tuple(p)

def parse_permutation(p):
    return tuple(list(p))

