from collections import defaultdict

def count_valid_substrings(s, constraints, k, l, r):
    char_count = [0] * 26
    char_count[s[0] - 'a'] += 1
    k_sum = char_count[:]
    res = char_count[:]
    for i in range(1, len(s)):
        for j in range(26):
            char_count[j] += k_sum[j] - char_count[j]
        if char_count[s[i] - 'a'] >= l[i] and char_count[s[i] - 'a'] <= r[i]:
            res[s[i] - 'a'] += char_count[s[i] - 'a']
        for j in range(26):
            char_count[j] = min(r[j], k_sum[j] - max(char_count[j], l[j]))
    result = defaultdict(int)
    for k, v in enumerate(res):
        for c in range(26):
            result[(k, c)] = v - min(res[k - 1][c], res[k - 1][c + 1])
    return sum(result[k % 26] for k in range(k) if result[k % 26])

