def escape_maze(maze, hero_position, exit_position):
    n, m = len(maze), len(maze[0])

    def valid_position(x, y):
        return 0 <= x < n and 0 <= y < m

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_bomb_unsafe(x, y):
        return x == hero_position[0] or y == exit_position[0] or (x, y) == exit_position

    def is_exit_safe(x, y):
        return x == exit_position[0] and y == exit_position[1]

    def update_position(x, y, move):
        if valid_position(x, y):
            maze[x][y] = "."
        else:
            maze[x][y] = move.strip("SSMNNE")

    def recursive_escape(x, y, i):
        if i == 6 and maze[x][y] != "E":
            return "No solution"
        if maze[x][y] == "E":
            return "SSMNNE"
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if not valid_position(nx, ny) or is_bomb_unsafe(nx, ny) or is_exit_safe(nx, ny):
                continue
            if maze[nx][ny] == "X":
                nx += 1
                ny += 1
            while is_bomb_unsafe(nx, ny) or maze[nx][ny] == "X":
                nx += 1
                ny += 1
            recursive_escape(nx, ny, i + 1)

    return recursive_escape(hero_position[0], hero_position[1], 0)

