from itertools import groupby

def max_profit(roads, races):
    costs = [0]
    for i, cost in enumerate(roads):
        if i + 1 not in costs:
            costs.append(i + 1)
        else:
            costs[-1] += 1
    cost_positions = {cost: pos for pos, cost in enumerate(costs)}
    raced_costs = sorted([(pos, cost) for pos, cost in cost_positions.items()])

    races = sorted(races, key=lambda race: cost_positions[race[1]])

    best_profit = 0
    for pos, cost in races:
        for suite in groupby(raced_costs, key=lambda race: race[0]):
            if pos in suite[0] or next(suite, None)[1] + cost < len(roads):
                break
        else:
            for sale in range(pos, pos + cost, cost):
                for suite in groupby(raced_costs, key=lambda race: race[1] + sale):
                    if next(suite, None)[1] + sale < len(roads):
                        break
            else:
                best_profit += cost * sale

    return best_profit

