def guess_nach_zombie(n, r, *args):
    n_minus_1, = args
    for i, n_i in enumerate(n_minus_1):
        # Ensure the zombie of rank r doesn't guess his own number
        if i == r:
            continue
        # The guess is the sum of all numbers minus the numbers observed by zombies of lower ranks
        guess = sum(n) - sum(n_i)
        # Check if the guess is unique
        if guess - sum(n_i) in n_minus_1:
            return guess - sum(n_i)
    # If no unique number is found, return the sum of all numbers minus the numbers observed by zombies of lower ranks
    return sum(n) - sum(n_minus_1)

