from itertools import combinations
from collections import defaultdict

def prefix_function(s):
    """ Computes the prefix function for a string """
    n = len(s)
    pi = [0] * n
    for i in range(1, n):
        needle, work = s[i:], s[:i]
        j = pi[i-1]
        while j > 0 and work[0] != needle[j]:
            j = pi[j-1]
        if work[0] == needle[j]:
            j += 1
        pi[i] = j
    return pi


def longest_common_prefix(s1, s2):
    """ Computes the length of the longest prefix T of s1
     that is a suffix of s2 """
    i = 0
    n1, n2 = len(s1), len(s2)
    s1, s2 = s1[::-1], s2[::-1]
    while i < n1 and i < n2 and s1[i] == s2[i]:
        i += 1
    return i


