    """ Computes possible matches with length at most L """
    matches = [[x] for x in range(1, len(s) - 1)]
    for i in range(len(s)-2, 0, -1):
        for j in range(i, 0, -1):
            if s[i] == s[j] and longest_common_prefix(s[:j], s[i:]):
                matches.append([s[j:i+1]] + matches[j-1])
    return matches

