def find_periods(num):
    periods = set()
    for start in range(1, len(num) // 2 + 1):
        found = True
        for i in range(start, len(num), start):
            if num[i] != num[i % start]:
                found = False
                break
        if found:
            periods.add(start)
    return periods

def check(serial_number, l, r, d):
    if l == r: 
        return "YES" if serial_number[l-1] % d == 0 else "NO"

    current_period = find_periods(serial_number[l-1:r])
    serial_number_l = serial_number[l]
    serial_number_r = serial_number[r-1]

    if d in current_period:
        return "NO"
    else:
        return "YES"

