import sys
from collections import defaultdict

def shortest_common_substring(s, queries):
    length = {}
    length[0] = 0
    prev = defaultdict(lambda: sys.maxsize)
    prev[0] = sys.maxsize

    for i in range(len(s)):
        for value in range(prev[0], length[0] + min(len(s) - prev[0] - 1, i - length[0])):
            if s[prev[0]:value + 1] == queries[0][prev[0]:value + 1]:
                length[value + 1] = value + 1
                prev[value + 1] = value + 1
            if s[value + previous: value + length[value] + 1] == queries[0][value - previous: value + length[value] + 1]:
                previous += 1
                length[value + previous] = value + length[value]

        previous = 0

    results = []
    for a, b in queries:
        i = distance(a, b)
        if i >= len(s):
            results.append(-1)
        else:
            results.append(s[:distance(a, b)])

    return results
