def max_profit(n, costs, race_times):
    costs.sort()
    profits = [0] * (n + 1)
    for race_idx, (lb, ub, profit) in enumerate(race_times):
        for road in range(lb - 1, ub):
            profits[road + 1] = max(profits[road + 1], profits[road] + profit)
    return max(profits)
